import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { aeoEnginesList, aeoEnginesPartialUpdate } from 'products/web_analytics/frontend/generated/api'
import type {
    AEOEngineSettingApi,
    PatchedAEOEngineSettingUpdateRequestApi,
} from 'products/web_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiVisibilityEnginesLogicValues {
    currentTeamIdStrict: number | string // teamLogic
    engines: AEOEngineSettingApi[] | null
    enginesError: boolean
    enginesLoading: boolean
    updatingEngines: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiVisibilityEnginesLogicActions {
    loadEngines: () => any
    loadEnginesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEnginesSuccess: (
        engines: AEOEngineSettingApi[],
        payload?: any
    ) => {
        engines: AEOEngineSettingApi[]
        payload?: any
    }
    updateEngine: (
        engine: string,
        change: PatchedAEOEngineSettingUpdateRequestApi
    ) => {
        change: PatchedAEOEngineSettingUpdateRequestApi
        engine: string
    }
    updateEngineFailure: (engine: string) => {
        engine: string
    }
    updateEngineSuccess: (setting: AEOEngineSettingApi) => {
        setting: AEOEngineSettingApi
    }
}

export type aiVisibilityEnginesLogicType = MakeLogicType<
    aiVisibilityEnginesLogicValues,
    aiVisibilityEnginesLogicActions
>

export const aiVisibilityEnginesLogic = kea<aiVisibilityEnginesLogicType>([
    path(['products', 'webAnalytics', 'contentAutopilot', 'aiVisibilityEnginesLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamIdStrict']],
    })),
    actions({
        updateEngine: (engine: string, change: PatchedAEOEngineSettingUpdateRequestApi) => ({ engine, change }),
        updateEngineSuccess: (setting: AEOEngineSettingApi) => ({ setting }),
        updateEngineFailure: (engine: string) => ({ engine }),
    }),
    loaders(({ values }) => ({
        engines: [
            null as AEOEngineSettingApi[] | null,
            {
                loadEngines: async () => await aeoEnginesList(String(values.currentTeamIdStrict)),
            },
        ],
    })),
    reducers({
        engines: {
            updateEngineSuccess: (state, { setting }) =>
                state ? state.map((row) => (row.engine === setting.engine ? setting : row)) : state,
        },
        enginesError: [
            false,
            {
                loadEngines: () => false,
                loadEnginesSuccess: () => false,
                loadEnginesFailure: () => true,
            },
        ],
        updatingEngines: [
            [] as string[],
            {
                updateEngine: (state, { engine }) => [...state, engine],
                updateEngineSuccess: (state, { setting }) => state.filter((engine) => engine !== setting.engine),
                updateEngineFailure: (state, { engine }) => state.filter((updating) => updating !== engine),
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        updateEngine: async ({ engine, change }) => {
            try {
                const setting = await aeoEnginesPartialUpdate(String(values.currentTeamIdStrict), engine, change)
                actions.updateEngineSuccess(setting)
                // pinned: analytics event name, renaming it breaks dashboards
                posthog.capture('web analytics ai visibility engine updated', {
                    engine: setting.engine,
                    enabled: setting.enabled,
                    frequency: setting.frequency,
                })
            } catch {
                lemonToast.error("Couldn't update the engine. Try again.")
                actions.updateEngineFailure(engine)
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadEngines()
    }),
])
